/*
 * The original linux ioctl numbering scheme was just a general
 * "anything goes" setup, where more or less random numbers were
 * assigned.  Sorry, I was clueless when I started out on this.
 *
 * On the alpha, we'll try to clean it up a bit, using a more sane
 * ioctl numbering, and also trying to be compatible with OSF/1 in
 * the process. I'd like to clean it up for the i386 as well, but
 * it's so painful recognizing both the new and the old numbers..
 */

const int32SignedToUnsigned = (int32) => Uint32Array.from(Int32Array.of(int32))[0];
const int32UnsignedToSigned = (uint32) => Int32Array.from(Uint32Array.of(uint32))[0];

const _IOC_NRBITS = 8 & 0xFF;
const _IOC_TYPEBITS = 8  & 0xFF;
const _IOC_SIZEBITS = 13  & 0xFF;
const _IOC_DIRBITS = 3  & 0xFF;


const _IOC_NRMASK = int32SignedToUnsigned((1 << _IOC_NRBITS) - 1) ; //0xFF=255
const _IOC_TYPEMASK = int32SignedToUnsigned((1 << _IOC_TYPEBITS) - 1); 
const _IOC_SIZEMASK = int32SignedToUnsigned((1 << _IOC_SIZEBITS) - 1);
const _IOC_DIRMASK = int32SignedToUnsigned((1 << _IOC_DIRBITS) - 1);

const _IOC_NRSHIFT = 0 & 0xFF;
const _IOC_TYPESHIFT = int32SignedToUnsigned(_IOC_NRSHIFT + _IOC_NRBITS)  & 0xFF; //0x08=8
const _IOC_SIZESHIFT = int32SignedToUnsigned(_IOC_TYPESHIFT + _IOC_TYPEBITS)  & 0xFF;//0x0F=16
const _IOC_DIRSHIFT = int32SignedToUnsigned(_IOC_SIZESHIFT + _IOC_SIZEBITS)  & 0xFF; //0x1D=29



/*
 * Direction bits _IOC_NONE could be 0, but OSF/1 gives it a bit.
 * And this turns out useful to catch old ioctl numbers in header
 * files for us.
 */

const _IOC_NONE = 1 & 0xFF;
const _IOC_READ = 2 & 0xFF;
const _IOC_WRITE = 4 & 0xFF;

//console.log({_IOC_NRBITS,_IOC_TYPEBITS,_IOC_SIZEBITS,_IOC_DIRBITS,_IOC_NRSHIFT,_IOC_TYPESHIFT,_IOC_SIZESHIFT,_IOC_DIRSHIFT});

const _IOC = (dir, type, nr, size) => {
    //_IOC_READ=> 0x40000000=1073741824 & _IOC_READ|_IOC_WRITE=> 
    //console.log({dir});
    dir=int32SignedToUnsigned(dir << _IOC_DIRSHIFT);
    //console.log({dir});

    type=int32SignedToUnsigned((type & 0xFF)  << _IOC_TYPESHIFT);
    nr=int32SignedToUnsigned((nr & 0xFF) << _IOC_NRSHIFT);

    size=int32SignedToUnsigned(size << _IOC_SIZESHIFT);

    return int32SignedToUnsigned( (dir | type | nr | size) & 0xFFFFFFFF );
}

/* used to create numbers */
const _IO = (type, nr) => { return _IOC(_IOC_NONE, (type), (nr), 0); }
const _IOR = (type, nr, size) => { return _IOC(_IOC_READ, (type), (nr), size); }
const _IOW = (type, nr, size) => { return _IOC(_IOC_WRITE, (type), (nr), size); }
const _IOWR = (type, nr, size) => { return _IOC(_IOC_READ | _IOC_WRITE, (type), (nr), size); }



/* Linerequest flags */
const GPIOHANDLE_REQUEST_INPUT = (1 << 0);
const GPIOHANDLE_REQUEST_OUTPUT = (1 << 1);
const GPIOHANDLE_REQUEST_ACTIVE_LOW = (1 << 2);
const GPIOHANDLE_REQUEST_OPEN_DRAIN = (1 << 3);
const GPIOHANDLE_REQUEST_OPEN_SOURCE = (1 << 4);
const GPIOHANDLE_REQUEST_BIAS_PULL_UP = (1 << 5);
const GPIOHANDLE_REQUEST_BIAS_PULL_DOWN = (1 << 6);
const GPIOHANDLE_REQUEST_BIAS_DISABLE = (1 << 7);

/* Line is in use by the kernel */
const GPIOLINE_FLAG_KERNEL = (1 << 0);
const GPIOLINE_FLAG_IS_OUT = (1 << 1);
const GPIOLINE_FLAG_ACTIVE_LOW = (1 << 2);
const GPIOLINE_FLAG_OPEN_DRAIN = (1 << 3);
const GPIOLINE_FLAG_OPEN_SOURCE = (1 << 4);


/**
 * struct gpiochip_info - Information about a certain GPIO chip
 * @name: the Linux kernel name of this GPIO chip
 * @label: a functional name for this GPIO chip, such as a product
 * number, may be NULL
 * @lines: number of GPIO lines on this chip
 */

// define the "snd_hwdep_info" struct type
/*
const gpiochip_info = StructType({
    name: ArrayType(ref.types.char, 32),
    label: ArrayType(ref.types.char, 32),
    lines: ref.types.uint32,
});
*/
//const gpiochip_info=Buffer.alloc(68);

const gpiochip_info = Struct.makeType({
    name: Struct.stringType(32),
    label: Struct.stringType(32),
    lines: Struct.type.uint32_t,
});

//console.log('gpiochip_info:',gpiochip_info);


/**
 * struct gpioline_info - Information about a certain GPIO line
 * @line_offset: the local offset on this GPIO device, fill this in when
 * requesting the line information from the kernel
 * @flags: various flags for this line
 * @name: the name of this GPIO line, such as the output pin of the line on the
 * chip, a rail or a pin header name on a board, as specified by the gpio
 * chip, may be NULL
 * @consumer: a functional name for the consumer of this GPIO line as set by
 * whatever is using it, will be NULL if there is no current user but may
 * also be NULL if the consumer doesn't set this up
 */

/*
const gpioline_info = StructType({
    line_offset: ref.types.uint32,
    flags:  ref.types.uint32,
    name: ArrayType(ref.types.char, 32),
    consumer: ArrayType(ref.types.char, 32)
});
*/

const gpioline_info=Buffer.alloc(72);


//const GPIO_GET_CHIPINFO_IOCTL= _IOR(0xB4, 0x01,  gpiochip_info); //1078244353
//const GPIO_GET_LINEINFO_IOCTL =_IOWR(0xB4, 0x02,  gpioline_info);

//const GPIO_GET_CHIPINFO_IOCTL=2151986177;
//const GPIO_GET_LINEINFO_IOCTL=3225990146;

const GPIO_GET_CHIPINFO_IOCTL=0x8044B401;
const GPIO_GET_LINEINFO_IOCTL=0xC048B402;

class gpiod {
    file_device_link;

    constructor(file_device_link) {
        this.file_device_link = file_device_link;
    }

    get_chip_info() {
        return new Promise((accept, reject) => {

            fs.open(this.file_device_link, 'r+', (err, fd) => {
                if (err) {
                    return reject(err);
                }

                var info = new Struct(gpiochip_info);

                var ret = ioctl(fd, GPIO_GET_CHIPINFO_IOCTL, info.ref());
                
                fs.close(fd);

                if(ret<0)return reject('Info reading error');

                accept(info.parse());
            });

        });
    }
}


module.exports = gpiod;